import type { Metadata } from "next";
import "./globals.css";

/**
 * What a screen reader, a browser tab and a link preview say about this product
 * before anything else does. It shipped as create-next-app's own placeholders
 * (`"Create Next App"` / `"Generated by create next app"`), which is the first
 * sentence a keyboard-or-screen-reader user hears — and it is false: nothing here
 * was generated by a template.
 *
 * The two `next/font/google` imports that used to sit above this were the only
 * build-time network egress in the project: they fetched Geist at build time and
 * published `--font-geist-sans` / `--font-geist-mono`, which nothing in the app
 * reads. Every surface here is `system-ui` (`globals.css`'s `.ui`, `.ctl-search
 * input`, `.credit`, `.panel`), and the stylesheet that did reference the two
 * variables — `src/app/page.module.css`, the rest of the template — is imported by
 * no file under `src/`. `src/test/a11y.test.ts` pins both facts, so the font
 * cannot come back as a "no visual change" claim nobody re-checked.
 */
export const metadata: Metadata = {
  title: "Moon Map — NASA lunar imagery and 1,585 IAU place names",
  description:
    "An offline-first map of the Moon: baked LROC albedo and colour imagery in a flat " +
    "paper view or a globe view, with 1,585 IAU Gazetteer place names, a scale readout, " +
    "deep-zoom Kaguya TC orthophoto over twelve regions, and every source credited.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
